const THEME_STORAGE_KEY = 'edb-theme';
const cleanUiLabel = (value) => value
  .replace(/[\p{Extended_Pictographic}\uFE0F]/gu, '')
  .replace(/\s+/g, ' ')
  .trim();

const getSystemPreference = () => {
  if (typeof window === 'undefined') return 'light';
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
};

const getInitialTheme = () => {
  if (typeof window === 'undefined') return 'light';
  if (typeof window.__INITIAL_THEME__ === 'string') return window.__INITIAL_THEME__;
  try {
    const stored = window.localStorage.getItem(THEME_STORAGE_KEY);
    if (stored === 'light' || stored === 'dark') return stored;
  } catch (e) { return getSystemPreference(); }
  return getSystemPreference();
};

// ── Animation plates ────────────────────────────────────────────────────────
// Every screen below is a real capture of the app, taken by
// content/screenshot-harness (`node capture.js anim`) and packed by
// scripts/build-anim.mjs. Each plate is a whole 16:9 display, which is exactly
// what the bezel wants, and the moving pieces the animations need on top,
// a travelling window, a cursor, a right-click menu, are separate plates so
// they can be animated over it. Nothing here draws a fake app.
const plate = (name) => `/anim/${name}.webp`;
const plateSrcSet = (name) => {
  const small = name === 'hero-mirror' ? 320 : name === 'window-float' ? 320 : name === 'menu-context' ? 240 : 640;
  const large = name === 'hero-mirror' ? 620 : name === 'window-float' ? 700 : name === 'menu-context' ? 520 : name === 'hero-desktop' ? 1400 : 1040;
  return `/anim/${name}-${small}.webp ${small}w, ${plate(name)} ${large}w`;
};

const Plate = ({ name, visible = true, eager = false, fit = 'cover', style = {}, className }) => (
  <img
    src={plate(name)}
    srcSet={plateSrcSet(name)}
    sizes="(min-width: 768px) 640px, 100vw"
    alt=""
    className={className}
    loading={eager ? 'eager' : 'lazy'}
    fetchPriority={eager ? 'high' : 'auto'}
    decoding="async"
    style={{
      position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: fit,
      opacity: visible ? 1 : 0, transition: 'opacity 0.55s ease', ...style,
    }}
  />
);

/** Crossfade between plates; `index` says which one is on top. */
const PlateStack = ({ frames, index, eager = false }) => (
  <div style={{ position: 'absolute', inset: 0, background: '#0b1220', overflow: 'hidden' }}>
    {frames.map((name, i) => <Plate key={name} name={name} visible={i === index} eager={eager && i === 0} />)}
  </div>
);

